// Block (composition) — a centered empty-collection placeholder.
// Stack owns arrangement; icon and action are consumer-supplied slots.
import { useId, type ReactNode, type Ref } from "react";
import { Stack } from "../layouts/Stack";
import "./EmptyState.css";

export interface EmptyStateProps {
  /** Optional decorative or illustrative icon. */
  icon?: ReactNode;
  /** Empty-state heading. */
  title: string;
  /** Supporting explanation or guidance. */
  description?: string;
  /** Consumer-supplied action, typically a Button. */
  action?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  className,
  ref,
}: EmptyStateProps) {
  const titleId = useId();

  return (
    <Stack
      as="section"
      ref={ref}
      aria-labelledby={titleId}
      align="center"
      gap="small"
      className={className ? `sd-emptystate ${className}` : "sd-emptystate"}
    >
      {icon}
      {/* spacing: attachment — the glyph heads the title under it.
          The name and its supporting line read as ONE unit, so they are a group at a tighter rung
          than the section's own — the same pair `PageHeader` groups. Flat siblings put the same
          12px between the title and its description as between the description and the action,
          which is what made the two read as three unrelated things. */}
      <Stack gap="x-small" align="center" className="sd-emptystate__heading">
        <h2 id={titleId} className="sd-emptystate__title sd-type-title-medium">
          {title}
        </h2>
        {description && (
          <p className="sd-emptystate__description sd-type-body-medium">{description}</p>
        )}
      </Stack>
      {action}
    </Stack>
  );
}

/* EmptyState.css — .sd-emptystate (Block)
   Arrangement only: a compact section centred in the column it is given; Stack owns flow. */
.sd-emptystate {
  width: 100%;
  text-align: center;
}

.sd-emptystate__title,
.sd-emptystate__description {
  margin: 0;
}

.sd-emptystate__description {
  color: var(--sd-color-text-muted);
}
